import { ChangeDetectionStrategy, Component } from '@angular/core';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { ProductService } from '../../services/product-service';
import { ActivatedRoute, Router } from '@angular/router';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-edit-product',
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './edit-product.html',
  styleUrl: './edit-product.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EditProduct {
productForm! : FormGroup;
productId! : number;
isLoading = true;

constructor(
    private fb: FormBuilder,
    private service: ProductService,
    private route: ActivatedRoute,
    private router: Router
  ) {}

    ngOnInit(): void {
    this.productForm = this.fb.group({
      productName: ['', Validators.required],
      catagoryName: ['', Validators.required],
      companyName: ['', Validators.required],
      productPrice: ['', Validators.required],
      hsNcode: ['', Validators.required]
    });
   const id = Number(this.route.snapshot.paramMap.get('id'));
    if (id) {
      this.productId = id;
      this.service.getProductByID(id).subscribe(product => {
        this.productForm.patchValue(product); 
        this.isLoading = false;
      });
    } else {
      this.isLoading = false;
    }
    }
    onCancel(){
    this.resetForm();
    this.router.navigate(['/product-master']);
  }
   onSubmit() {
  if (this.productForm.invalid) 
    return;

   const dto = {
    ...this.productForm.value,
   }

  console.log("Submitting Party:", dto);

  this.service.updateProduct(this.productId, dto).subscribe({
    next: () => {
      alert('✅ Party updated successfully');
      this.resetForm();
    },
    error: (err) => {
      console.error('❌ Upload failed', err);
      alert(err.error?.message || 'Upload failed. Please try again.');
    }
  });

  this.router.navigate(['/product-master'])
}


  private resetForm() {
    this.productForm.reset();
  }
  }
  
